===== features/invoices/AllInvoicesPage.tsx =====
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { money } from '../../ui/money';

// An invoice as the all-invoices endpoint returns it: which project it is for (by NAME, joined
// server-side), its amount, and its lifecycle status (the stage it is at). See InvoicesAllGet.
export type InvoiceView = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

// One place listing every invoice across all projects, each row showing the project it is for and
// the stage it is at. Server data is read with useQuery under ['invoices', 'all'] — the key still
// starts with 'invoices', so a write that invalidates ['invoices'] refreshes this list too (rule 5).
export function AllInvoicesPage() {
  const invoices = useQuery({
    queryKey: ['invoices', 'all'],
    queryFn: () => getJson<InvoiceView[]>('/api/invoices/all'),
  });

  const rows = invoices.data ?? [];

  return (
    <section data-testid="all-invoices">
      {rows.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <table data-testid="all-invoices-table">
          <thead>
            <tr>
              <th>Project</th>
              <th>Amount</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((i) => (
              <tr key={i.id} data-testid={`invoice-row-${i.id}`}>
                <td data-testid="invoice-project">{i.projectName}</td>
                <td data-testid="invoice-amount">{money(Number(i.amount))}</td>
                <td data-testid="invoice-status">{i.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}
===== features/invoices/InvoicesPanel.tsx =====
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
import { money } from '../../ui/money';

// An invoice as the server returns it: which project it belongs to, its amount, and its lifecycle
// status (DRAFT until sent, SENT until paid, then PAID).
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

// A project's invoices: the list scoped to this project, their derived total, and the form to add a
// new one. Server data is read with useQuery under the ['invoices'] key and changed with
// useMutation + invalidateQueries — never copied into state, never hand-maintained. The only
// useState is the amount the user is currently typing (rule 4).
export function InvoicesPanel({ projectId }: { projectId: number }) {
  const queryClient = useQueryClient();
  // The sort lives in the URL (owned by features/invoices/sortByDue.slot.tsx). The panel reads the
  // same key and asks the server for the ordered list, so it stays a single source of truth — no
  // server data copied into state or re-sorted by hand. The key still starts with 'invoices', so
  // writes that invalidateQueries({ queryKey: ['invoices'] }) still refresh it.
  const [sort] = useSearchParam('invoiceSort', asString);
  const invoices = useQuery({
    queryKey: ['invoices', sort],
    queryFn: () =>
      getJson<Invoice[]>(
        sort ? `/api/invoices?sort=${encodeURIComponent(sort)}` : '/api/invoices',
      ),
  });

  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');

  const create = useMutation({
    mutationFn: () =>
      postJson<Invoice>('/api/invoices', { projectId, amount: Number(amount) }),
    onSuccess: () => {
      setAmount('');
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });

  // Sending a draft invoice is a write: POST then invalidate ['invoices'] so the row re-renders with
  // its new status (DRAFT -> SENT) — never hand-maintained. The server also records the send to the
  // audit file.
  const send = useMutation({
    mutationFn: (id: number) => postJson<Invoice>('/api/invoices/send', { id }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });

  // Marking an invoice paid is a write: POST then invalidate ['invoices'] so the row re-renders with
  // its new status — never hand-maintained. The server also records the payment to the audit file.
  // Payment is only offered once the invoice has been sent (SENT -> PAID).
  const pay = useMutation({
    mutationFn: (id: number) => postJson<Invoice>('/api/invoices/pay', { id }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });

  const rows = (invoices.data ?? []).filter((i) => i.projectId === projectId);
  const total = rows.reduce((sum, i) => sum + Number(i.amount), 0);

  return (
    <section data-testid="project-invoices">
      <form
        data-testid="invoice-form"
        onSubmit={(e) => {
          e.preventDefault();
          const value = Number(amount);
          if (!amount.trim() || Number.isNaN(value) || value <= 0) {
            setError('Amount must be more than zero.');
            return;
          }
          setError('');
          create.mutate();
        }}
      >
        <input
          data-testid="invoice-form-amount"
          type="number"
          step="0.01"
          placeholder="Amount"
          value={amount}
          onChange={(e) => {
            setAmount(e.target.value);
            setError('');
          }}
        />
        <button data-testid="invoice-form-submit" type="submit">
          Add invoice
        </button>
        {error && (
          <p data-testid="invoice-form-amount-error" role="alert">
            {error}
          </p>
        )}
      </form>

      <div data-testid="project-invoices-toolbar">
        <InvoicesToolbar.Slot />
      </div>

      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Issued</th>
            <th>Due</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((i) => (
            <tr key={i.id} data-testid={`invoice-row-${i.id}`}>
              <td data-testid="invoice-amount">{money(Number(i.amount))}</td>
              <td data-testid="invoice-issued">{i.issuedDate}</td>
              <td data-testid="invoice-due">{i.dueDate}</td>
              <td data-testid="invoice-status">{i.status}</td>
              <td>
                {i.status === 'DRAFT' && (
                  <button
                    type="button"
                    data-testid={`invoice-send-${i.id}`}
                    onClick={() => send.mutate(i.id)}
                  >
                    Send
                  </button>
                )}
                {i.status === 'SENT' && (
                  <button
                    type="button"
                    data-testid={`invoice-pay-${i.id}`}
                    onClick={() => pay.mutate(i.id)}
                  >
                    Mark paid
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td data-testid="project-invoices-total">{money(total)}</td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}
===== features/invoices/sortByDue.slot.tsx =====
import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The sort-by-due-date control — its own file, filling the project invoices toolbar slot. It OWNS
// the `invoiceSort` URL key (rule 4: a sort outlives a click, so it lives in the URL, not useState).
// The invoices panel reads the same key and asks the server for the ordered list; nothing is passed
// between them. Carries data-testid="invoice-sort-due" (the test contract).
function SortByDue() {
  const [sort, setSort] = useSearchParam('invoiceSort', asString);
  const active = sort === 'due';
  return (
    <button
      type="button"
      data-testid="invoice-sort-due"
      aria-pressed={active}
      onClick={() => setSort(active ? undefined : 'due')}
    >
      Sort by due date
    </button>
  );
}

export const contribution = InvoicesToolbar.fill({ order: 10, Component: SortByDue });
===== features/invoices/invoices.slot.tsx =====
import { ProjectDetail } from '../../slots/defs/projectDetail';
import { InvoicesPanel } from './InvoicesPanel';

// The invoices' presence on a project's detail page — its own file, filling the project-detail
// slot. The detail route was written once and is not touched to add this; the panel queries for its
// own data (['invoices']) scoped to the project it is handed.
export const contribution = ProjectDetail.fill({
  order: 10,
  Component: InvoicesPanel,
});
